package com.masterclass.inventory.controller; import com.masterclass.inventory.dto.SaleDtos.*; import com.masterclass.inventory.service.SaleService; import jakarta.validation.Valid; import lombok.RequiredArgsConstructor; import org.springframework.http.*; import org.springframework.web.bind.annotation.*; import java.util.*; @RestController @RequestMapping("/api/v1/sales") @RequiredArgsConstructor public class SaleController { private final SaleService service; @PostMapping public ResponseEntity<SaleResponse> create(@Valid @RequestBody SaleRequest r){return ResponseEntity.status(HttpStatus.CREATED).body(service.create(r));} @GetMapping public List<SaleResponse> list(){return service.list();} @GetMapping("/{id}") public SaleResponse get(@PathVariable Long id){return service.get(id);} }
